import 'dart:convert';import 'package:http/http.dart' as http;import 'package:supabase_flutter/supabase_flutter.dart';class WorkforceRepository{WorkforceRepository(this.base,this.client);final String base;final SupabaseClient client;Future<Map<String,dynamic>> summary()async{final t=client.auth.currentSession?.accessToken;if(t==null)throw Exception('Sign in required.');final r=await http.get(Uri.parse('$base/api/v1/workforce/summary'),headers:{'Authorization':'Bearer $t'});if(r.statusCode>=400)throw Exception('Workforce unavailable.');return Map<String,dynamic>.from(jsonDecode(r.body));}}
